ESP = ESP - 4; wu(M, ESP - 7245824, EAX)
ESP = ESP - 4
ICALL(ru(M, band(ECX) - 7245824))
EAX = band(EBX + EBX*2)
ESP = ESP - 4; wu(M, ESP - 7245824, 7667072)
wu(M, ESP - 7245772, EAX)
EAX = band(EAX + EDI)
EDX = band(ESI + EAX*4)
EAX = ru(M, 421452)
ESP = ESP - 4; wu(M, ESP - 7245824, EDX)
ESP = ESP - 4
ICALL(ru(M, band(EAX) - 7245824))
EDX = ru(M, 421452)
EAX = band(EBP + EBP*2)
EAX = band(EAX + EDI)
ESP = ESP - 4; wu(M, ESP - 7245824, 7667072)
ECX = band(ESI + EAX*4)
ESP = ESP - 4; wu(M, ESP - 7245824, ECX)
ESP = ESP - 4
ICALL(ru(M, band(EDX) - 7245824))
ECX = ru(M, ESP - 7245756)
EDX = ru(M, 421452)
EAX = EBX
ESP = ESP - 4; wu(M, ESP - 7245824, ECX)
do local n = band(4, 31)
if n ~= 0 then local a = EAX
FC = band(rshift(a, 32 - n), 1) ~= 0
local r = band(lshift(a, n), 4294967295)
FR = r; FZ = r == 0; FS = band(r, 2147483648) ~= 0; FP = PAR[band(r, 0xff)]; FO = false
EAX = r
end end
EDI = band(EAX + ESI)
ESP = ESP - 4; wu(M, ESP - 7245824, EDI)
ESP = ESP - 4
ICALL(ru(M, band(EDX + 20) - 7245824))
ECX = ru(M, 421452)
EAX = EBP
do local n = band(4, 31)
if n ~= 0 then local a = EAX
FC = band(rshift(a, 32 - n), 1) ~= 0
local r = band(lshift(a, n), 4294967295)
FR = r; FZ = r == 0; FS = band(r, 2147483648) ~= 0; FP = PAR[band(r, 0xff)]; FO = false
EAX = r
end end
EAX = band(EAX + ESI)
ESP = ESP - 4; wu(M, ESP - 7245824, EDI)
ESP = ESP - 4; wu(M, ESP - 7245824, EAX)
ESP = ESP - 4
ICALL(ru(M, band(ECX) - 7245824))
EDX = ru(M, ESP - 7245740)
EAX = band(EBP + EBP*2)
EAX = band(EAX + EBX)
ESP = ESP - 4; wu(M, ESP - 7245824, EDX)
EDI = band(ESI + EAX*4)
EAX = ru(M, 421452)
ESP = ESP - 4; wu(M, ESP - 7245824, EDI)
ESP = ESP - 4
ICALL(ru(M, band(EAX + 16) - 7245824))
ECX = ru(M, ESP - 7245736)
EAX = ru(M, 421452)
ESP = ESP + 64
ECX = band(ECX + EBP)
EDX = band(ESI + ECX*4)
ESP = ESP - 4; wu(M, ESP - 7245824, EDI)
ESP = ESP - 4; wu(M, ESP - 7245824, EDX)
ESP = ESP - 4
ICALL(ru(M, band(EAX + 4) - 7245824))
ESP = ESP + 8
EDI = ru(M, ESP - 7245824); ESP = ESP + 4
ESI = ru(M, ESP - 7245824); ESP = ESP + 4
EBP = ru(M, ESP - 7245824); ESP = ESP + 4
EBX = ru(M, ESP - 7245824); ESP = ESP + 4
ESP = ESP + 4
do return end
end
end
end

-- registers are per module: calls between modules go through the shared register file ctx.R
local R = ctx.R
local function LOAD() EAX, EBX, ECX, EDX, ESI, EDI, EBP, ESP, FT, FSW = R[1], R[2], R[3], R[4], R[5], R[6], R[7], R[8], R[9], R[10] end
local function SAVE() R[1], R[2], R[3], R[4], R[5], R[6], R[7], R[8], R[9], R[10] = EAX, EBX, ECX, EDX, ESI, EDI, EBP, ESP, FT, FSW end
for a, f in pairs(XF) do
	ctx.XF[a] = function() LOAD(); f(); SAVE() end
end
setmetatable(XF, {__index = function(t, a)
	local g = ctx.XF[a]
	if not g then error(string.format("NR2003 build: call to unknown %08x", a)) end
	local s = function() SAVE(); g(); LOAD() end
	t[a] = s
	return s
end})
end

